BEGIN;
SET search_path=public,extensions;
SELECT no_plan();
SELECT has_function('public','claim_notifications',ARRAY['integer'],'worker claims notifications');
SELECT has_function('public','finish_notification',ARRAY['bigint','uuid','boolean'],'worker acknowledges lease');
SELECT ok(NOT has_function_privilege('anon','public.claim_notifications(integer)','EXECUTE'),'anonymous cannot claim notification emails');
SELECT ok(NOT has_function_privilege('authenticated','public.claim_notifications(integer)','EXECUTE'),'ordinary account cannot claim notification emails');
SELECT ok(NOT has_function_privilege('anon','public.finish_notification(bigint,uuid,boolean)','EXECUTE'),'anonymous cannot acknowledge notifications');
SELECT ok(NOT has_function_privilege('authenticated','public.finish_notification(bigint,uuid,boolean)','EXECUTE'),'ordinary account cannot acknowledge notifications');
SELECT ok(has_function_privilege('service_role','public.claim_notifications(integer)','EXECUTE'),'service worker can claim');
SELECT ok(has_function_privilege('service_role','public.finish_notification(bigint,uuid,boolean)','EXECUTE'),'service worker can finish');
SELECT ok(has_function_privilege('service_role','public.close_expired_auctions()','EXECUTE'),'service worker can close expired state');
SET LOCAL ROLE anon;
SELECT throws_ok('SELECT public.claim_notifications(1)','42501',NULL,'anonymous claim call denied');
SELECT throws_ok('SELECT public.finish_notification(1,gen_random_uuid(),true)','42501',NULL,'anonymous acknowledge call denied');
RESET ROLE;
SET LOCAL ROLE authenticated;
SELECT throws_ok('SELECT public.claim_notifications(1)','42501',NULL,'ordinary account claim call denied');
SELECT throws_ok('SELECT public.finish_notification(1,gen_random_uuid(),true)','42501',NULL,'ordinary account acknowledge call denied');
RESET ROLE;
-- Isolate the lease fixture from any existing application notifications.
UPDATE app.notification_outbox SET next_attempt_at=clock_timestamp()+interval '1 day' WHERE delivered_at IS NULL;
INSERT INTO auth.users(id,email,email_confirmed_at) VALUES('77777777-0000-4000-8000-000000000001','notification-fixture@example.test',clock_timestamp());
CREATE TEMP TABLE notification AS WITH n AS(INSERT INTO app.notification_outbox(user_id,event,entity_id) VALUES('77777777-0000-4000-8000-000000000001','message.received','77777777-0000-4000-8000-000000000002') RETURNING id) SELECT id FROM n;
CREATE TEMP TABLE first_lease AS SELECT public.claim_notifications(1000) j;
SELECT is(jsonb_array_length((SELECT j FROM first_lease)),1,'eligible notification claimed once');
SELECT is((SELECT j->0->>'email' FROM first_lease),'notification-fixture@example.test','only service RPC joins recipient email');
SELECT is((SELECT array_agg(k ORDER BY k) FROM jsonb_object_keys((SELECT j->0 FROM first_lease)) k),ARRAY['email','entity_id','event','id','lease_token']::text[],'claim response exact minimal keys');
SELECT is((SELECT attempts FROM app.notification_outbox WHERE id=(SELECT id FROM notification)),1,'claim increments attempt counter');
SELECT is(jsonb_array_length(public.claim_notifications(50)),0,'active lease not claimed twice');
SELECT ok(NOT public.finish_notification((SELECT id FROM notification),gen_random_uuid(),true),'wrong lease token cannot acknowledge');
SELECT ok(public.finish_notification((SELECT id FROM notification),(SELECT (j->0->>'lease_token')::uuid FROM first_lease),false),'current lease failure acknowledged');
SELECT is((SELECT last_error FROM app.notification_outbox WHERE id=(SELECT id FROM notification)),'delivery_failed','only fixed error code persisted');
SELECT ok((SELECT next_attempt_at>clock_timestamp()+interval '20 seconds' FROM app.notification_outbox WHERE id=(SELECT id FROM notification)),'failed delivery waits before retry');
SELECT is(jsonb_array_length(public.claim_notifications(50)),0,'retry delay respected');
UPDATE app.notification_outbox SET next_attempt_at=clock_timestamp()-interval '1 second' WHERE id=(SELECT id FROM notification);
CREATE TEMP TABLE retry_lease AS SELECT public.claim_notifications(50) j;
SELECT is((SELECT attempts FROM app.notification_outbox WHERE id=(SELECT id FROM notification)),2,'retry increments attempts');
SELECT ok((SELECT j->0->>'lease_token' FROM first_lease)<>(SELECT j->0->>'lease_token' FROM retry_lease),'retry rotates lease token');
SELECT ok(NOT public.finish_notification((SELECT id FROM notification),(SELECT (j->0->>'lease_token')::uuid FROM first_lease),true),'stale lease cannot acknowledge retry');
UPDATE app.notification_outbox SET lease_until=clock_timestamp()-interval '1 second' WHERE id=(SELECT id FROM notification);
SELECT ok(NOT public.finish_notification((SELECT id FROM notification),(SELECT (j->0->>'lease_token')::uuid FROM retry_lease),true),'expired lease cannot acknowledge');
CREATE TEMP TABLE final_lease AS SELECT public.claim_notifications(50) j;
SELECT ok(public.finish_notification((SELECT id FROM notification),(SELECT (j->0->>'lease_token')::uuid FROM final_lease),true),'current delivery finalized');
SELECT ok((SELECT delivered_at IS NOT NULL AND lease_token IS NULL AND lease_until IS NULL AND last_error IS NULL FROM app.notification_outbox WHERE id=(SELECT id FROM notification)),'success clears lease and error');
SELECT is(jsonb_array_length(public.claim_notifications(50)),0,'delivered notification never reclaimed');
INSERT INTO app.notification_outbox(user_id,event,attempts,next_attempt_at) VALUES('77777777-0000-4000-8000-000000000001','message.received',5,clock_timestamp()-interval '1 hour');
SELECT is(jsonb_array_length(public.claim_notifications(50)),0,'five-attempt ceiling enforced');
SELECT is(jsonb_array_length(public.claim_notifications(-5)),0,'negative limit safely yields no claims');
-- Independent service-worker transactions are exercised by test-concurrency.mjs.
SELECT * FROM finish();
ROLLBACK;
